{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "The closest analogue sharing the 4-methoxybiphenyl piperazine core entered pig brain after IV injection with a peak SUV of ~2.5 g/mL, demonstrating meaningful BBB penetration for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "The same core with an unsubstituted piperazine entered rat brain rapidly (peak ~1.2 SUV), independently supporting CNS access for the biphenyl-methoxy piperazine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A methoxyphenyl piperazine butyl-amide analogue showed high mouse brain uptake (4.99 %ID/g at 10 min), indicating that amide-linked piperazine analogues in this series can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A structurally related piperazine butyl-amide D3 ligand entered the brain quickly and showed high brain penetration after IV administration, supporting CNS access for long-chain piperazine amides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A lower-similarity methoxyphenyl piperazine butyl-amide analogue was poorly brain-penetrant and acted as an ABC transporter substrate, flagging a possible efflux liability, but this is outweighed by the higher-similarity permeable analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogues sharing the 4-methoxybiphenyl piperazine core show robust brain uptake in PET and biodistribution studies, and related piperazine-amide ligands are brain-penetrant. Although one lower-similarity analogue is an efflux substrate, the overall transferred experimental evidence supports meaningful CNS access for the query.",
  "evidence_gaps": [
    "No direct brain, plasma, or CSF measurement exists for the exact query molecule.",
    "Efflux liability of the query was not experimentally characterized.",
    "The long hexanamide linker may alter permeability relative to shorter-chain analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

